#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NativeFontRuleBlink {
    None,
    Slow,
    Rapid,
}

impl NativeFontRuleBlink {
    fn parse(value: &str) -> Option<Self> {
        match value {
            "None" => Some(Self::None),
            "Slow" => Some(Self::Slow),
            "Rapid" => Some(Self::Rapid),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NativeHorizontalContentAlignment {
    Left,
    Center,
    Right,
}

impl NativeHorizontalContentAlignment {
    fn parse(value: &str) -> Option<Self> {
        match value {
            "Left" => Some(Self::Left),
            "Center" => Some(Self::Center),
            "Right" => Some(Self::Right),
            _ => None,
        }
    }

    fn offset(self, gap: u32) -> u32 {
        match self {
            Self::Left => 0,
            Self::Center => gap / 2,
            Self::Right => gap,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NativeVerticalContentAlignment {
    Top,
    Center,
    Bottom,
}

impl NativeVerticalContentAlignment {
    fn parse(value: &str) -> Option<Self> {
        match value {
            "Top" => Some(Self::Top),
            "Center" => Some(Self::Center),
            "Bottom" => Some(Self::Bottom),
            _ => None,
        }
    }

    fn offset(self, gap: u32) -> u32 {
        match self {
            Self::Top => 0,
            Self::Center => gap / 2,
            Self::Bottom => gap,
        }
    }
}

