    fn effective_overlay_font(&self, font: &Option<NativeFontConfig>) -> Option<NativeFontConfig> {
        font.clone().or_else(|| {
            self.window_frame_appearance
                .font
                .as_deref()
                .map(native_font_config)
        })
    }

