fn interpolate_badge_format(badge_format: &str, context: &BadgeInterpolationContext<'_>) -> String {
    let mut output = String::new();
    let mut rest = badge_format;
    while let Some(start) = rest.find("\\(") {
        output.push_str(&rest[..start]);
        if let Some(variable) = rest[start..].strip_prefix(BADGE_USER_VAR_PREFIX) {
            let Some(end) = variable.find(')') else {
                output.push_str(&rest[start..]);
                return output;
            };

            let name = &variable[..end];
            if let Some(value) = context.user_vars.get(name) {
                output.push_str(value);
            }
            rest = &variable[end + 1..];
        } else if let Some(next) =
            interpolate_known_badge_variable(&mut output, rest, start, context)
        {
            rest = next;
        } else if let Some(end) = rest[start + 2..].find(')') {
            rest = &rest[start + 2 + end + 1..];
        } else {
            output.push_str("\\(");
            rest = &rest[start + 2..];
        }
    }
    output.push_str(rest);
    output
}

fn pane_progress_label(progress: PaneProgress) -> String {
    match progress {
        PaneProgress::None => String::new(),
        PaneProgress::Percentage(value) => format!("{value}%"),
        PaneProgress::Error(value) => format!("err:{value}%"),
        PaneProgress::Indeterminate => "~".to_owned(),
    }
}

const fn tab_bar_new_tab_label() -> &'static str {
    " + "
}

fn integrated_title_button_default_tab_bar_label(
    button: NativeIntegratedTitleButton,
) -> &'static str {
    match button {
        NativeIntegratedTitleButton::Hide => " . ",
        NativeIntegratedTitleButton::Maximize => " - ",
        NativeIntegratedTitleButton::Close => " X ",
    }
}

fn split_pane_render_rect(
    source: PaneRenderRect,
    new_pane_id: rssh_core::PaneId,
    direction: SplitDirection,
    source_size_delta: i16,
) -> Option<(PaneRenderRect, PaneRenderRect, PaneSeparator)> {
    match direction {
        SplitDirection::Right => {
            split_pane_render_rect_right(source, new_pane_id, source_size_delta)
        }
        SplitDirection::Left => split_pane_render_rect_left(source, new_pane_id, source_size_delta),
        SplitDirection::Down => split_pane_render_rect_down(source, new_pane_id, source_size_delta),
        SplitDirection::Up => split_pane_render_rect_up(source, new_pane_id, source_size_delta),
    }
}

fn split_pane_render_rect_right(
    source: PaneRenderRect,
    new_pane_id: rssh_core::PaneId,
    source_size_delta: i16,
) -> Option<(PaneRenderRect, PaneRenderRect, PaneSeparator)> {
    if source.columns < 3 || source.rows == 0 {
        return None;
    }

    let source_columns = adjusted_split_source_size(
        source.columns,
        source.columns.saturating_sub(1) / 2,
        source_size_delta,
    );
    let new_columns = source
        .columns
        .saturating_sub(source_columns)
        .saturating_sub(1);
    if source_columns == 0 || new_columns == 0 {
        return None;
    }

    let next_source = PaneRenderRect {
        columns: source_columns,
        ..source
    };
    let new_rect = PaneRenderRect {
        pane_id: new_pane_id,
        row: source.row,
        column: source
            .column
            .saturating_add(source_columns)
            .saturating_add(1),
        rows: source.rows,
        columns: new_columns,
    };
    let separator = PaneSeparator {
        row: source.row,
        column: source.column.saturating_add(source_columns),
        rows: source.rows,
        columns: 1,
        direction: SplitDirection::Right,
        source_pane: source.pane_id,
        new_pane: new_pane_id,
    };

    Some((next_source, new_rect, separator))
}

