    fn set_badge_format(app: &mut NativeWindowApp, format: &str) {
        let sequence = format!(
            "\x1b]1337;SetBadgeFormat={}\x07",
            STANDARD.encode(format.as_bytes())
        );
        app.handle_pty_output(sequence.as_bytes()).unwrap();
    }

    struct ChildProcessGuard(Child);

    impl ChildProcessGuard {
        fn id(&self) -> u32 {
            self.0.id()
        }
    }

    impl Drop for ChildProcessGuard {
        fn drop(&mut self) {
            let _ = self.0.kill();
            let _ = self.0.wait();
        }
    }

    #[cfg(target_os = "windows")]
    fn spawn_sleeping_child(cwd: &Path) -> io::Result<ChildProcessGuard> {
        Command::new("powershell.exe")
            .args([
                "-NoLogo",
                "-NoProfile",
                "-Command",
                "Start-Sleep -Seconds 30",
            ])
            .current_dir(cwd)
            .spawn()
            .map(ChildProcessGuard)
    }

    #[cfg(not(target_os = "windows"))]
    fn spawn_sleeping_child(cwd: &Path) -> io::Result<ChildProcessGuard> {
        Command::new("sh")
            .args(["-c", "sleep 30"])
            .current_dir(cwd)
            .spawn()
            .map(ChildProcessGuard)
    }

    fn test_home_dir() -> Option<PathBuf> {
        std::env::var_os("USERPROFILE")
            .filter(|value| !value.is_empty())
            .map(PathBuf::from)
            .or_else(|| {
                let drive = std::env::var_os("HOMEDRIVE")?;
                let path = std::env::var_os("HOMEPATH")?;
                if drive.is_empty() || path.is_empty() {
                    return None;
                }
                let mut home = std::ffi::OsString::from(drive);
                home.push(path);
                Some(PathBuf::from(home))
            })
            .or_else(|| {
                std::env::var_os("HOME")
                    .filter(|value| !value.is_empty())
                    .map(PathBuf::from)
            })
    }

